join (values ('Classes', 'Core Circuit with Yvette', 'CORE training workout builds strength, stability, and endurance in the muscles that support your spine—including the abs, glutes, hips, and lower back.', 185000, 'IDR', 0), ('Classes', 'The Body Reset & Release', 'A deeply restorative healing journey to unwind pain, release long-held tension, calm your nervous system, and restore your natural ease of movement.', 444000, 'IDR', 1), ('Classes', 'Critical Alignment Yoga', 'A modern, anatomy-based approach to yoga that helps you move with greater freedom, strength, and awareness.', null, null, 2), ('Classes', 'BodyPump HEAVY', 'Designed for maximum muscle growth by using heavier weights than traditional BODYPUMP.', 185000, 'IDR', 3), ('Classes', 'BODYPUMP', 'A full-body, high-rep strength training class that uses barbells and motivating music to tone, sculpt, and build muscular endurance.', 185000, 'IDR', 4), ('Classes', 'Kundalini Activation - Release to Rise with Anna', 'A fusion of Kundalini Activation, Shamanic practices, Light Language, and NLP Parts Integration designed to facilitate deep Energetic Liberation.', 555000, 'IDR', 5), ('Classes', 'Strength Development Class', 'Muscle is medicine. This class focuses on muscular strength and muscle hypertrophy using slower movements while lifting a heavier load.', 185000, 'IDR', 6), ('Classes', 'Quantum Reset', 'A guided breath, movement, and visualization class that shifts your state and drops you into the version of you that’s already living your vision.', 555000, 'IDR', 7), ('Classes', 'Energetic Healing & Breathwork with Roo', 'A transformative class that combines breathwork and Kundalini energy activation, taking you deeper into your being.', 555000, 'IDR', 8), ('Classes', 'Somatic Soul Retrieval with Kristy', 'A deeply guided journey to reclaim lost fragments of yourself through somatic movement, breathwork, and emotional release.', 555000, 'IDR', 9), ('Classes', 'Kundalini Activation - Release to Rise with Anna', 'A powerful session designed to facilitate deep Energetic Liberation, inviting you into a vortex of sound, movement, and transformation.', 555000, 'IDR', 10), ('Classes', 'BodyPump HEAVY', 'Prioritizes technique and strength over high-repetition endurance, focusing on controlled movements and heavier weights.', 185000, 'IDR', 11), ('Classes', 'BODYPUMP', 'Expands energetically while strengthening the physical body to hold and integrate more light and vitality.', 185000, 'IDR', 12), ('Classes', 'Critical Alignment Yoga', 'Restores mobility, enhances posture, and develops functional strength from the inside out using precise instruction.', null, null, 13), ('Classes', 'Core Circuit with Yvette', 'A core workout developed to enhance strength and stability in supporting muscles using resistance bands and bodyweight exercises.', 185000, 'IDR', 14), ('Classes', 'The Body Reset & Release', 'Focuses on physical healing and nervous system regulation through intentional movement and breath-led transitions.', 444000, 'IDR', 15)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

