with target as (
  select slug from venues where slug = 'udara-bali-yoga-detox-and-spa-organic-ocean' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Healing Treatment', 1, 'draft', 'partial', 'https://www.udara-bali.com/wp-content/uploads/2025/04/Udara-healing-Treatments.pdf', 'Official Udara Bali Yoga Detox & Spa / Organic Ocean menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'c85e90a470a4c19c064d55f89ccb000bc75499b2253f095f5b5c351f0384fbb4', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'spa')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Sound Healing', 0), ('Water Healing Treatment', 1), ('Reiki', 2), ('Water Massage', 3), ('Hyperbaric Oxygen Chamber Treatment (HBOT)', 4), ('Acupuncture', 5), ('Cupping', 6), ('Hypnotherapy', 7), ('Quit Smoking with Hypnosis', 8), ('Healing Breathwork', 9), ('Your Voice, Your Mirror', 10), ('Theta Healing', 11), ('Dream Machine', 12), ('Personal Training', 13), ('Kundalini Activation & Bodywork', 14), ('Aerial Thai Massage', 15)) as s(name, pos)
  returning id, name
