r | Tomato | Flat Parsley | Coriander | Red Onion | Lemon Dressing | Couscous', 80000, 'IDR', 6), ('Sides', 'Mediterranean Salad', 'Eggplant | Zucchini | Paprika | Feta | Rucola | Almond | Olive Oil Dressing', 95000, 'IDR', 7)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

