insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Massage 90 minute treatment', 'Massage 90 minute treatment', null, 420000, 'IDR', 0), ('Massage 90 minute treatment', 'The Herbalist', 'Steamed herbal poultices are pressed into muscles combined with a deeply nurturing massage using traditional Jamu herb infused oil made exclusively for Koa. Enjoy a chamomile tea eye pillow to finish your refreshing therapeutic treatment.', 520000, 'IDR', 1), ('Massage 90 minute treatment', 'Balinese Hands', 'A beautiful massage combining kneading and rhythmic strokes of balinese hands and our dreamy ylangylang, coconut and vanilla oil blend will have you floating in tropical island bliss. We will treat your feet to a ylang-ylang scrub.', 290000, 'IDR', 2), ('Massage 90 minute treatment', 'Mother Earth', 'Your body is caressed with the flowing strokes of warm basalt stones combined with soothing massage using our unique oil blend of Agarwood, Patchouli and Musk. Fall into a deep state of relaxation with a chai infused eye pillow. Connect with earth energy in this deeply calming and grounding treatment.', 290000, 'IDR', 3), ('Massage 90 minute treatment', 'Chakra Dhara', 'This treatment is based on ancient Indian holistic healing traditions. We start by awakening the skin by dry brushing the body. This improves circulation and removes impurities. Followed by an invigorating Ayurvedic style massage using a deeply nourishing warmed oil blend of Neroli, Rose, white musk with a hint of cinnamon.', 290000, 'IDR', 4), ('Massage 90 minute treatment', 'Aura Harmony', 'This signature massage is a fusion of aura cleansing spray, chakra crystal layout, be lulled into a state of bliss with an aromatherapy body massage, drifting on the scent of lavender & bergamot working on both the physical and auric body you will feel an amazing lightness of being. We finish off your treatment with a singing bowl.', 290000, 'IDR', 5), ('Massage 90 minute treatment', 'Nuad Boran', 'Originating from Buddhist monks this dry style massage combines stretching, gentle twisting and acupressure. No oil is applied and kimono is supplied. Finish off with a dry head and face massage while enjoying a lemongrass infused hot towel foot wrap.', 290000, 'IDR', 6), ('Massage 90 minute treatment', 'Chi Reviver', 'This massage is a powerful energy reviver. Firm massage, kneading and pressure point techniques get deep into the muscles, relieving tension and improving the chi energy meridians. Eucalyptus, rosemary and lavender oils assist in the healing and rebalancing of the life force. Finished with a eucalyptus hot towel neck roll.', 290000, 'IDR', 7), ('Massage 90 minute treatment', 'Reflexology', 'Begin with a refreshing lavender foot soak, followed by our signature pressure point foot massage from the knees down. This refined reflexology treatment helps restore balance, enhance circulation, and awaken the body’s natural healing energy, perfect for deep relaxation and revitalized legs.', 290000, 'IDR', 8), ('Massage 90 minute treatment', 'Hot Stone Reflexology', 'Start with a refreshing lavender foot soak, lemon pandan foot scrub and peppermint green tea foot mask. Then enjoy an intensive foot and lower leg massage using acupressure on precise points on the feet to open meridians and enhance the bodies natural healing abilities. To bring balance to the treatment we finish with hot stone shoulder and neck massage.', 290000, 'IDR', 9), ('Massage 90 minute treatment', 'Shirodhara', 'This Ayurvedic healing technique combines indian head massage include face, neck, shoulder massage completed by pouring warm coconut oil on the third eye area. This is the perfect treatment to completely quieten a busy mind having a soothing and balancing effect on brain cells while gently activating our intuition. Treatment 60 mins + 15 mins shower time.', 320000, 'IDR', 10), ('+Plus treatments 30 minute', 'Customise your massage with our add ons', null, 200000, 'IDR', 0), ('Spa Rituals', 'Build your own pamper package', 'Receive discounts based on the duration of your package', null, null, 0), ('Yoga Package', 'Yoga Class + 60 Minute treatment', 'Body Massage, Feet Reflexology', 380000, 'IDR', 0), ('Yoga Package', 'Yoga Class + 90 minutes Body Massage', null, 500000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

