join (values ('Membership', 'Daily Access', 'All Facilities', 300000, 'IDR', 0), ('Membership', 'Gym Access', 'gym & recovery', 250000, 'IDR', 1), ('Membership', 'Recovery Access', 'Day Pass (recovery only)', 200000, 'IDR', 2), ('Membership', '3 Days Pass', 'IN A ROW (All Facilities)', 650000, 'IDR', 3), ('Membership', '4 Days Pass', 'IN A ROW (All Facilities)', 770000, 'IDR', 4), ('Membership', '5 Days Pass', 'IN A ROW (All Facilities)', 900000, 'IDR', 5), ('Membership', 'Weekly Pass', 'IN A ROW (All Facilities)', 1000000, 'IDR', 6), ('Membership', '10 Times Pass', 'Valid for 2 Month (All Facilities)', 1750000, 'IDR', 7), ('Membership', '5PM Club Membership', 'Gym access only (5PM to closing)', 1200000, 'IDR', 8), ('Membership', 'Recovery Only', 'Valid for 1 Month (All Facilities)', 1000000, 'IDR', 9), ('Membership', '1 Month Membership', 'All Facilities', 1800000, 'IDR', 10), ('Membership', '2 Month Membership', 'All Facilities', 3000000, 'IDR', 11), ('Membership', '3 Month Membership', 'All Facilities', 4000000, 'IDR', 12), ('Membership', '6 Month Membership', 'All Facilities', 7000000, 'IDR', 13), ('Membership', '12 Month Membership', 'All Facilities', 12000000, 'IDR', 14)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

