with target as (
  select slug from venues where slug = 'de-nyuh-spa-seminyak' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'De Nyuh Spa Kuta''s Menu', 1, 'draft', 'partial', 'https://www.denyuhspa.com/kuta', 'Official De Nyuh Spa Seminyak menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '8368e2064e4dac85aa9fb5647bafddbe7266249b01642a078dc8e1fd7875fc36', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'spa')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Signature Packages', 0), ('Body Scrubs', 1), ('Body Masks', 2)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Signature Packages', 'DE NYUH BLISS', 'This blissful package is combination of Balinese traditional massage and body scrub or facial. Starting with foot wash ritual followed by Balinese traditional massage to relax your body. Completed with your choice of body scrub or facial to soften and brighten your skin.', 300000, 'IDR', 0), ('Signature Packages', 'MAXIMUM SENSATION', 'This maximum package is whole treatment in one package. Starting with foot wash ritual followed by Balinese traditional massage to relax your body, continue with your choice of body scrub, express facial to brighten your skin, end with body mask to soft and smooth your skin.', 450000, 'IDR', 1), ('Signature Packages', 'SET MENU', 'Customize your own package from our selection of starter, main and dessert.', 350000, 'IDR', 2), ('Signature Packages', 'FOOT MASSAGE', 'Relieve your tired foot with express foot therapy using friction and long strokes from sole to upper calf.', 135000, 'IDR', 3), ('Signature Packages', 'EXPRESS FACIAL', 'Pamper your self with our instant glow express facial that will bring back your youthful glow. Awaken your light and radiate your beauty.', null, null, 4), ('Signature Packages', 'BACK NECK AND SHOULDER', 'This massage is a fantastic cure for traveler''s syndrome; stiff and sore neck and shoulders. The therapist focuses on the upper half of your body. Relieve stress and bring back relaxation after a long day of activities.', null, null, 5), ('Signature Packages', 'BALINESE MASSAGE', 'Experience the wonder of traditional Balinese technique that includes long, slow strokes. Kneading, and stretching and light acupressure stimulation.', 250000, 'IDR', 6), ('Signature Packages', 'REVITALIZE MASSAGE', 'Using muscle melting and deep pressure massage movements. Each treatment is customized to focus on your area of concern.', 250000, 'IDR', 7), ('Signature Packages', 'DE NYUH SIGNATURE FACIAL', 'This heavenly facial will make you feel like goddess with its natural recipe will leave your skin glow and fresh.', 250000, 'IDR', 8), ('Signature Packages', 'REFLEXOLOGY', 'Inspired by an ancient Chinese philosophy that the vital organs of the body are connected and mirrored to reflex points in the feet by energy channels called ''MERIDIENS'' this deeply relaxing foot massage aims to unblock any latent energy and revitalize mind and body. Reflexology can improve health and is a blissful as it beneficial.', 250000, 'IDR', 9), ('Signature Packages', 'HOT STONE MASSAGE', 'We use heated stones to melt away your tensions. Therapeutic heat is slowly released into the belly of the muscle for a completely new body experience. The stones are pleased on key energy points. The combination of traditional massage and deep penetrating heat will balance the spirit and transport you the ultimate state of bliss.', 290000, 'IDR', 10), ('Body Scrubs', 'ROSE PETAL SCRUB', 'The rose petal scrub consists of rice powder and fresh rose petals, and a nourishing oil blend which has an anti-aging benefits that will help to reduce fine lines, tighten and rehydrate skin. It will slow downs the visible signs of ageing, leaving skin firmer and perfect for sensitive skin.', 150000, 'IDR', 0), ('Body Scrubs', 'KEMIRI & LEMON BASIL SCRUB', 'This fragrant scrub combines kemiri (candlenut) and lemon basil to revive mature and tired looking skin. Rich in vitamins with antioxidant and antl-bacterial mechanisms, it improves skin texture and tone.', null, null, 1), ('Body Scrubs', 'COCONUT & SEA SALT SCRUB', 'Made of fresh coconut and coconut milk, this scrub also combined with sea salt. Good for removing dead skin cell and deep cleaning, leaving the body smooth and silky.', null, null, 2), ('Body Scrubs', 'JAVANESE LULUR', 'This relieving exfoliation and body cleansing ritual which has been used in royal palaces of Central Java since 17th century helps to soften refine and deep cleanse the skin. This exfoliation treatment assists the detoxification process by sloughing away dry skin.', null, null, 3), ('Body Masks', 'TRADITIONAL BALINESE BOREH', 'Made from several kinds of Balinese traditional herbs, this traditional Balinese blend will help to improve the blood circulation and detoxify your body and leaving a warm sensation lingering after the treatment.', 150000, 'IDR', 0), ('Body Masks', 'SUNBURN & SENSITIVE SKIN WRAP', 'Feel the heat leave your sun burnt body with a blend of fresh cucumber, honey and yoghurt. The vast majority of wraps comprise moisturizing ingredients to hydrate, nourish and smoothen your skin.', null, null, 1), ('Body Masks', 'NATURAL YOGURT MASK', 'Natural yogurt contains mild exfoliating properties to remove dead skin cells. Leave your body moisturized by the acid content from the yogurt. Perfect to softens and revitalizes the skin.', null, null, 2)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where slug = 'dong-oman-cultural-dining-at-tonys-villas-and-resort' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Dong Oman Cultural Dining', 1, 'draft', 'partial', 'https://www.balitonys.com/wp-content/uploads/sites/28/2024/09/Dong-Oman-Cultural-Dining-Menu.pdf', 'Official Dong Oman Cultural Dining at Tonys Villas and Resort menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'f1ce40f3f9e102e85a4a259caaecb98a71ed76b391223da2b59d676cd24b31c2', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('FOOD', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
